prismaticChemtrails.glsl:
#version 300 es
precision highp float;

uniform float time;
uniform vec2 resolution;
uniform vec2 fullResolution;

out vec4 fragColor;

#define TAU 6.283185307179586
#define PI 3.141592653589793

uniform float dispersion;    // 0.0-1.0, radial spectral dispersion strength
uniform float driftAmount;   // 0.0-0.5, wisp drift oscillation amplitude
uniform float hueOffset;     // 0.0-1.0, iridescent sheen hue shift
uniform float mixWisp;       // 0.0-1.0, wisp modulation of dispersion
uniform float prismIntensity; // 0.0-2.0, prism effect strength
uniform float trailDensity;  // 0.5-8.0, chemtrail wisp density

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float valueNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
        v += amp * valueNoise(p);
        p = p * 2.02 + vec2(1.7, 9.2);
        amp *= 0.5;
    }
    return v;
}

// Saturated rainbow palette: red at t=0, through spectrum to violet
vec3 rainbowPalette(float t) {
    vec3 c = 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
    // boost saturation
    float g = dot(c, vec3(0.299, 0.587, 0.114));
    return mix(vec3(g), c, 1.6);
}

// Pale steel-blue/white base tint for chemtrail wisps
vec3 wispTint(float density) {
    vec3 base = vec3(0.85, 0.88, 0.92);
    return mix(vec3(1.0), base, clamp(density, 0.0, 1.0));
}

float gaussianWeight(float x, float sigma) {
    return exp(-(x * x) / (2.0 * sigma * sigma));
}

void main() {
    vec2 uv = gl_FragCoord.xy / resolution;
    vec2 centered = uv - 0.5;
    centered.x *= resolution.x / resolution.y;

    // ═══════════════════════════════════════════════════════════════════════════
    // LOOPING PRIMITIVES - ALL ANIMATION MUST USE THESE
    // time goes 0→1, so t goes 0→TAU, completing exactly one cycle
    // ═══════════════════════════════════════════════════════════════════════════
    float t = time * TAU;           // Converts time 0→1 to radians 0→TAU
    vec2 timeCircle = vec2(cos(t), sin(t));  // For noise sampling - traces a circle
    float pulse = 0.5 + 0.5 * sin(t);        // 0→1→0 smooth oscillation
    float wave = sin(t);                      // -1→1→-1 smooth oscillation

// Radial prism bloom: sharp at the optical center, wider at the edges.
    float aspect = resolution.x / resolution.y;
    float centerDist = length(centered);
    float edgeBloom = smoothstep(0.0, 0.85, centerDist);
    vec2 radialDirection = centered / max(centerDist, 0.0001);
    radialDirection.x /= aspect;

    vec2 wispDomain = vec2(uv.x, uv.y * 6.0) * trailDensity;
    vec2 driftA = vec2(driftAmount * sin(t), 0.0);
    vec2 driftB = vec2(-driftAmount * cos(t), 0.0);
    vec2 organicMotion = timeCircle * 0.3;

    float localWispA = fbm(wispDomain + driftA + organicMotion);
    float localWispB = fbm(wispDomain * 1.23 + driftB
                         - organicMotion + vec2(8.1, 3.7));
    float localDensity = smoothstep(
        0.36, 0.69, localWispA * 0.65 + localWispB * 0.35
    );

    float breathing = 0.8 + 0.2 * sin(t);
    float dispersionWidth = dispersion * breathing * 0.16;
    dispersionWidth *= mix(1.0, 0.35 + 1.35 * localDensity, mixWisp);
    dispersionWidth *= clamp(prismIntensity, 0.0, 2.0);

    float sheenShift = hueOffset + 0.05 * sin(t * 2.0);
    vec3 spectralSum = vec3(0.0);
    vec3 spectralNormalization = vec3(0.0);
    vec3 neutralSum = vec3(0.0);
    float totalWeight = 0.0;

    // Each tap views a complete airy sky with dissolving horizontal trails.
    for (int tap = 0; tap < 18; ++tap) {
        float tapPosition = float(tap) / 17.0;
        float signedPosition = tapPosition - 0.5;
        vec2 sampleUV = uv + radialDirection
                     * signedPosition * dispersionWidth * centerDist;

        vec3 sky = mix(
            vec3(0.88, 0.94, 0.99),
            vec3(0.34, 0.63, 0.87),
            smoothstep(0.0, 1.0, sampleUV.y)
        );

        vec2 domain = vec2(sampleUV.x, sampleUV.y * 6.0)
                    * trailDensity;
        float noiseA = fbm(domain + driftA + organicMotion);
        float noiseB = fbm(domain * 1.23 + driftB
                        - organicMotion + vec2(8.1, 3.7));
        float vapor = smoothstep(0.34, 0.73, 0.65 * noiseA + 0.35 * noiseB);

        // Explicit narrow trail coverage, warped and eroded into soft wisps.
        float trails = 0.0;
        for (int trail = 0; trail < 6; ++trail) {
            float id = float(trail);
            float seed = hash(vec2(id + 1.0, 17.2));
            float layerSign = (trail == 0 || trail == 2 || trail == 4)
                            ? 1.0 : -1.0;
            float pendulum = layerSign > 0.0
                           ? driftAmount * sin(t)
                           : -driftAmount * cos(t);
            float trailX = sampleUV.x + pendulum;
            float baseHeight = 0.13 + id * 0.145;
            float bend = 0.013 * sin(trailX * 7.0 + seed * TAU);
            bend += (noiseA - 0.5) * 0.075;
            float distanceToTrail = abs(sampleUV.y - baseHeight - bend);
            float width = (0.007 + 0.010 * seed)
                        * (0.65 + 0.35 * vapor)
                        * sqrt(max(trailDensity, 0.5) / 3.0);
            float coverage = 1.0 - smoothstep(width, width * 3.6, distanceToTrail);
            float segment = smoothstep(-0.15, 0.12, trailX + seed * 0.2)
                          * (1.0 - smoothstep(0.78, 1.2, trailX - seed * 0.15));
            float dissolution = smoothstep(0.28, 0.65,
                mix(noiseA, noiseB, seed));
            trails = max(trails, coverage * segment * dissolution);
        }

        float density = clamp(trails * 0.94 + vapor * 0.23, 0.0, 1.0);
        vec3 paleWisp = wispTint(density);
        vec3 sheen = clamp(rainbowPalette(
            sampleUV.x * 0.55 + sampleUV.y * 0.22
            + sheenShift + noiseB * 0.25
        ), 0.0, 1.0);
        sheen = mix(vec3(1.0), sheen, 0.65);
        float sheenMask = smoothstep(0.25, 0.85, density) * edgeBloom;
        sheenMask *= clamp(prismIntensity * 0.65, 0.0, 0.9);
        vec3 cloudColor = mix(paleWisp, sheen, sheenMask);
        vec3 sceneColor = mix(sky, cloudColor, density * 0.88);

        // Positive saturated full-spectrum weights, red outward/violet inward.
        vec3 spectrum = clamp(
            rainbowPalette((1.0 - tapPosition) * 0.78), 0.0, 1.0
        );
        spectrum = mix(vec3(0.08), vec3(1.0), spectrum);
        float weight = gaussianWeight(signedPosition, 0.27);
        weight *= 1.0 - smoothstep(0.38, 0.62, abs(signedPosition));

        spectralSum += sceneColor * spectrum * weight;
        spectralNormalization += spectrum * weight;
        neutralSum += sceneColor * weight;
        totalWeight += weight;
    }

    vec3 dispersedColor = spectralSum / max(spectralNormalization, vec3(0.0001));
    vec3 neutralColor = neutralSum / max(totalWeight, 0.0001);
    float prismBlend = clamp(prismIntensity, 0.0, 1.0);
    vec3 color = mix(neutralColor, dispersedColor, prismBlend);
    color = max(color, vec3(0.0));

//  Color Output 
    // Gentle center-weighted exposure so the frame core stays bright and airy
    // while the prismatic bloom dissolves outward toward the frame edges.
    float centerProtect = 1.0 - 0.18 * edgeBloom;
    color *= centerProtect;

    // Soft tonal shaping to keep pastels airy without clipping highlights.
    color = color / (color + vec3(0.85)) * 1.65;
    color = pow(clamp(color, 0.0, 1.0), vec3(0.92));

    // Final pastel lift toward a bright sky-white base.
    color = mix(color, mix(color, vec3(1.0), 0.12), smoothstep(0.4, 1.0, centerDist));

    fragColor = vec4(color, 1.0);
}

psychedelicplasmatunnel.glsl:
#version 300 es
precision highp float;

uniform float time;
uniform vec2 resolution;
uniform vec2 fullResolution;

out vec4 fragColor;

#define TAU 6.283185307179586
#define PI 3.141592653589793

uniform float colorShift;   // 0.0-1.0, palette phase offset (default 0)
uniform float complexity;   // 1.0-8.0, FBM octaves (default 5)
uniform float intensity;    // 0.0-2.0, overall brightness/glow (default 1)
uniform float scale;        // 0.5-20.0, plasma pattern zoom (default 4)
uniform float speed;        // 0.1-5.0, flight speed multiplier (default 1)
uniform float swirl;        // 0.0-3.0, vortex twist amount (default 1)

// ---------- Pure helper functions ----------

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// Smooth 2D value noise
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Rotate a 2D point
vec2 rot(vec2 p, float a) {
    float c = cos(a);
    float s = sin(a);
    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);
}

// 4D-ish noise: 2D value noise extended with a vec2 time-circle offset (timeCircle noise)
// Pure: caller supplies the animated offset.
float noise4(vec2 p, vec2 tc) {
    // blend two noise samples driven by the time-circle components
    float n1 = noise(p + tc * 2.7 + 13.1);
    float n2 = noise(p - tc * 1.9 + 7.7);
    return mix(n1, n2, 0.5 + 0.5 * dot(normalize(tc + 1e-6), vec2(0.7071, 0.7071)) * 0.5);
}

// Per-octave rotated + scaled FBM (avoids axial alignment artifacts)
float fbm(vec2 p, float octaves, vec2 tc) {
    float v = 0.0;
    float amp = 0.5;
    mat2 m = mat2(0.8, 0.6, -0.6, 0.8); // rotation
    for (int i = 0; i < 8; i++) {
        if (float(i) >= octaves) break;
        v += amp * noise4(p, tc);
        p = m * p * 2.03 + vec2(1.7, 9.2);
        amp *= 0.5;
    }
    return v;
}

// IQ cosine palette
vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(TAU * (c * t + d));
}

// Wrap angle into n repeating slices, seamless (no hard seam)
float sliceWrap(float angle, float n) {
    return angle * n / TAU;
}

void main() {
    vec2 uv = gl_FragCoord.xy / resolution;
    vec2 centered = uv - 0.5;
    centered.x *= resolution.x / resolution.y;

    // ═══════════════════════════════════════════════════════════════════════════
    // LOOPING PRIMITIVES - ALL ANIMATION MUST USE THESE
    // time goes 0→1, so t goes 0→TAU, completing exactly one cycle
    // ═══════════════════════════════════════════════════════════════════════════
    float t = time * TAU;           // Converts time 0→1 to radians 0→TAU
    vec2 timeCircle = vec2(cos(t), sin(t));  // For noise sampling - traces a circle
    float pulse = 0.5 + 0.5 * sin(t);        // 0→1→0 smooth oscillation
    float wave = sin(t);                      // -1→1→-1 smooth oscillation

// Visible structures: perspective wormhole walls, flowing plasma,
    // luminous racing rings, and a dark, fog-obscured vanishing point.
    vec2 p = rot(centered, t);
    float rawRadius = length(p);
    float pixelRadius = 1.5 / max(resolution.y, 1.0);
    float radius = sqrt(rawRadius * rawRadius + max(0.018, pixelRadius)
                                               * max(0.018, pixelRadius));
    float angle = atan(p.y, p.x);
    float depth = 0.3 / radius;

    // Breathing flight and depth-dependent vortex twist.
    float flight = speed * sin(t * 2.0);
    float tunnelDepth = depth + flight;
    float twist = swirl * (0.8 + 0.2 * sin(t * 2.0));
    float wallAngle = angle + twist * depth;

    // Circular embedding makes all eight angular slices genuinely seamless.
    float angularPhase = wallAngle * 8.0;
    vec2 angularDomain = vec2(cos(angularPhase), sin(angularPhase));
    float patternScale = max(scale, 0.5);
    vec2 domain = angularDomain * (0.32 * patternScale)
                + vec2(0.57, 0.83) * tunnelDepth * patternScale;

    // Reduce unresolved detail near the vanishing point.
    float footprint = max(length(fwidth(domain)), 0.0001);
    float detail = clamp(complexity - max(0.0, log2(footprint * 2.0)),
                         1.0, 8.0);

    // Two-stage self-warping produces organic, liquid plasma on the walls.
    vec2 warpA = vec2(
        fbm(domain + vec2(4.7, 1.3), detail, timeCircle),
        fbm(domain + vec2(-3.2, 8.1), detail, timeCircle)
    );
    vec2 warpedDomain = domain + 2.5 * (warpA - 0.5);
    vec2 warpB = vec2(
        fbm(warpedDomain + vec2(9.2, -2.8), detail, timeCircle),
        fbm(warpedDomain + vec2(1.6, 6.4), detail, timeCircle)
    );
    float plasma = fbm(warpedDomain + 2.2 * (warpB - 0.5),
                       detail, timeCircle);

    // Smooth filament coverage, with derivative-aware edge widths.
    float filamentDistance = abs(plasma - 0.49);
    float filamentAA = max(fwidth(plasma), 0.002);
    float filaments = 1.0 - smoothstep(0.012, 0.065 + filamentAA,
                                      filamentDistance);
    float liquidLight = smoothstep(0.22, 0.76, plasma);

    // Perspective depth contours form luminous rings moving with the flight.
    float ringPhase = tunnelDepth * TAU * 1.8
                    + 0.38 * sin(angularPhase)
                    + 0.55 * (plasma - 0.5);
    float ringDistance = abs(sin(ringPhase));
    float ringAA = max(fwidth(ringPhase), 0.001);
    float ringVisibility = 1.0 - smoothstep(0.3, 1.8, ringAA);
    float rings = (1.0 - smoothstep(0.025, 0.14 + ringAA,
                                  ringDistance)) * ringVisibility;
    float ringHalo = exp(-5.0 * ringDistance) * ringVisibility;
    float ringPulse = 0.5 + 0.5 * sin(t * 3.0);

    // IQ cosine palette: one exact rainbow phase revolution per loop.
    float colorPhase = colorShift + plasma * 1.45
                     + 0.075 * tunnelDepth
                     + 0.12 * sin(angularPhase);
    vec3 rainbow = 0.5 + 0.5 * cos(
        vec3(t) + TAU * (vec3(colorPhase) + vec3(0.0, 0.33, 0.67))
    );
    vec3 plasmaColor = mix(vec3(0.08, 0.015, 0.15), rainbow,
                           0.55 + 0.45 * liquidLight);
    vec3 ringColor = mix(rainbow, vec3(0.75, 0.92, 1.0), 0.48);

    float fog = 0.42;
    float depthFog = exp(-depth * fog);
    float coreMask = smoothstep(0.0, 0.035, rawRadius);
    vec3 color = plasmaColor * (0.22 + 1.15 * liquidLight);
    color += rainbow * filaments * 1.7;
    color += ringColor * rings * (0.8 + 1.2 * ringPulse);

    // Same-pass soft bloom around plasma filaments and ring contours.
    float filamentBloom = exp(-18.0 * filamentDistance);
    color += mix(rainbow, vec3(1.0), 0.22)
           * (0.45 * filamentBloom + 0.35 * pow(filaments, 3.0));
    color += ringColor * ringHalo * (0.18 + 0.32 * ringPulse);
    color *= depthFog * coreMask;

    // Gamma lift, saturation boost, and subtle three-cycle intensity pulse.
    color = pow(max(color, vec3(0.0)), vec3(0.85));
    float luma = dot(color, vec3(0.2126, 0.7152, 0.0722));
    color = max(mix(color, vec3(luma), -0.22), vec3(0.0));
    color *= max(intensity, 0.0) * (0.94 + 0.06 * sin(t * 3.0));

fragColor = vec4(color, 1.0);
}

chromeicosahedroninterior.glsl:
#version 300 es
precision highp float;

uniform float time;
uniform vec2 resolution;

out vec4 fragColor;

#define TAU 6.283185307179586
#define PI 3.141592653589793

uniform int reflections;      // 2-10, number of internal mirror bounces
uniform float glowIntensity;  // 0.0-3.0, brightness of edge glow effect
uniform float chromeShift;    // 0.0-0.1, chromatic aberration strength
uniform float cameraOffset;   // 0.0-0.4, camera distance from center

// Hash functions for procedural generation
float hash(float p) {
    return fract(sin(p * 127.1) * 43758.5453);
}

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec3 hash3(vec2 p) {
    vec3 q = vec3(dot(p, vec2(127.1, 311.7)),
                  dot(p, vec2(269.5, 183.3)),
                  dot(p, vec2(419.2, 371.9)));
    return fract(sin(q) * 43758.5453);
}

// Value noise - pure math, noiseOffset enables animation when passed from main
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Golden ratio for icosahedron geometry
const float PHI = 1.618033988749895;

// Icosahedron SDF - signed distance (negative inside)
float sdIcosahedron(vec3 p, float r) {
    vec3 n = normalize(vec3(PHI, 1.0, 0.0));
    vec3 ap = abs(p);
    float a = dot(ap, n);
    float b = dot(ap, n.yzx);
    float c = dot(ap, n.zxy);
    return max(max(a, b), c) - r;
}

// Get icosahedron face normal at point
vec3 icosahedronNormal(vec3 p) {
    vec3 n = normalize(vec3(PHI, 1.0, 0.0));
    vec3 ap = abs(p);
    vec3 sp = sign(p + 1e-6);

    float a = dot(ap, n);
    float b = dot(ap, n.yzx);
    float c = dot(ap, n.zxy);

    if (a >= b && a >= c) return sp * n;
    if (b >= a && b >= c) return sp.yzx * n.yzx;
    return sp.zxy * n.zxy;
}

// Fresnel reflectance (Schlick approximation)
float fresnel(vec3 viewDir, vec3 normal, float f0) {
    float cosTheta = max(dot(-viewDir, normal), 0.0);
    return f0 + (1.0 - f0) * pow(1.0 - cosTheta, 5.0);
}

// Chrome metallic palette - t is 0-1 position, NOT time
vec3 chromePalette(float t) {
    vec3 silver = vec3(0.9, 0.92, 0.95);
    vec3 cyan = vec3(0.7, 0.9, 1.0);
    vec3 gold = vec3(1.0, 0.95, 0.85);
    vec3 blue = vec3(0.7, 0.75, 0.85);

    t = clamp(t, 0.0, 0.9999);
    float segment = t * 4.0;
    int idx = int(segment);
    float blend = segment - float(idx);

    if (idx == 0) return mix(silver, cyan, blend);
    if (idx == 1) return mix(cyan, blue, blend);
    if (idx == 2) return mix(blue, gold, blend);
    return mix(gold, silver, blend);
}

// Procedural environment for reflections
// noiseOffset passed from main for animation
vec3 proceduralEnvironment(vec3 dir, vec2 noiseOffset) {
    float theta = atan(dir.z, dir.x);
    float phi = asin(clamp(dir.y, -1.0, 1.0));

    float band = sin(theta * 3.0) * cos(phi * 2.0);
    band += noise(vec2(theta, phi) * 5.0 + noiseOffset) * 0.3;

    float palettePos = band * 0.5 + 0.5;
    vec3 col = chromePalette(palettePos);
    col *= 0.8 + 0.2 * noise(dir.xz * 8.0 + noiseOffset);

    return col;
}

// Rotation helpers
vec3 rotateY(vec3 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}

vec3 rotateX(vec3 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(p.x, c * p.y - s * p.z, s * p.y + c * p.z);
}

// Edge glow at grazing angles
float edgeGlow(vec3 viewDir, vec3 normal) {
    float edge = 1.0 - abs(dot(viewDir, normal));
    return pow(max(edge, 0.0), 3.0);
}

// Reflect ray inside icosahedron and accumulate color
vec3 reflectRay(vec3 dir, vec3 normal) {
    return reflect(dir, normal);
}

void main() {
    vec2 uv = gl_FragCoord.xy / resolution;
    vec2 centered = uv - 0.5;
    centered.x *= resolution.x / resolution.y;

    // ═══════════════════════════════════════════════════════════════════════════
    // LOOPING PRIMITIVES - ALL ANIMATION MUST USE THESE
    // time goes 0→1, so t goes 0→TAU, completing exactly one cycle
    // ═══════════════════════════════════════════════════════════════════════════
    float t = time * TAU;           // Converts time 0→1 to radians 0→TAU
    vec2 timeCircle = vec2(cos(t), sin(t));  // For noise sampling - traces a circle
    float pulse = 0.5 + 0.5 * sin(t);        // 0→1→0 smooth oscillation
    float wave = sin(t);                      // -1→1→-1 smooth oscillation

// ═══════════════════════════════════════════════════════════════════════════
    // MAIN EFFECT LOGIC - Chrome Icosahedron Interior
    // ═══════════════════════════════════════════════════════════════════════════

    float icoRadius = 1.0;

    // Camera orbiting inside the icosahedron - uses wave for smooth back-and-forth
    vec3 camPos = vec3(
        timeCircle.x * cameraOffset,
        wave * cameraOffset * 0.3,
        timeCircle.y * cameraOffset
    );

    // Camera look direction with gentle oscillation
    vec3 camTarget = vec3(wave * 0.1, sin(t * 2.0) * 0.05, 0.0);
    vec3 camForward = normalize(camTarget - camPos);
    vec3 camRight = normalize(cross(vec3(0.0, 1.0, 0.0), camForward));
    vec3 camUp = cross(camForward, camRight);

    // Ray direction through pixel
    vec3 rayDir = normalize(camForward + centered.x * camRight + centered.y * camUp);

    // Final accumulated color with chromatic aberration
    vec3 finalColor = vec3(0.0);

    // Trace 3 rays for chromatic aberration (R, G, B channels)
    for (int channel = 0; channel < 3; channel++) {
        float aberrationOffset = (float(channel) - 1.0) * chromeShift;
        vec3 traceDir = normalize(rayDir + camRight * aberrationOffset);
        vec3 traceOrigin = camPos;

        vec3 channelColor = vec3(0.0);
        float channelAtten = 1.0;

        // Reflection bounces inside icosahedron
        for (int bounce = 0; bounce < 10; bounce++) {
            if (bounce >= reflections) break;

            // Ray march to find icosahedron surface from inside
            float marchDist = 0.0;
            vec3 hitPos = traceOrigin;

            for (int step = 0; step < 48; step++) {
                hitPos = traceOrigin + traceDir * marchDist;
                float d = -sdIcosahedron(hitPos, icoRadius);
                if (d < 0.001) break;
                marchDist += max(d * 0.6, 0.002);
                if (marchDist > 4.0) break;
            }

            // Surface normal pointing inward
            vec3 normal = -icosahedronNormal(hitPos);

            // Fresnel - chrome is highly reflective
            float fresnelVal = fresnel(traceDir, normal, 0.85);

            // Edge glow - bright at grazing angles, pulsing
            float glow = edgeGlow(traceDir, normal);
            float pulsingGlow = glow * glowIntensity * (0.7 + 0.5 * pulse);

            // Sample procedural environment in reflection direction
            vec3 reflectDir = reflect(traceDir, normal);
            vec3 envColor = proceduralEnvironment(reflectDir, timeCircle * 0.5);

            // Accumulate environment color through attenuation
            channelColor += channelAtten * envColor * (1.0 - fresnelVal) * 0.4;

            // Add edge glow with animated palette position
            float palettePos = 0.5 + 0.3 * sin(t + float(bounce) * 0.8);
            vec3 glowCol = chromePalette(palettePos);
            channelColor += channelAtten * glowCol * pulsingGlow;

            // Attenuate for next bounce
            channelAtten *= fresnelVal * 0.88;

            // Set up next bounce
            traceDir = reflectDir;
            traceOrigin = hitPos + traceDir * 0.01;
        }

        // Final environment contribution after all bounces
        vec3 finalEnv = proceduralEnvironment(traceDir, timeCircle * 0.5);
        channelColor += channelAtten * finalEnv;

        // Assign to appropriate color channel
        if (channel == 0) finalColor.r = channelColor.r;
        else if (channel == 1) finalColor.g = channelColor.g;
        else finalColor.b = channelColor.b;
    }

    // Add central bright spot with animated intensity
    float centerDist = length(centered);
    float centerGlow = exp(-centerDist * 4.0) * 0.3 * (0.8 + 0.4 * pulse);
    finalColor += chromePalette(pulse) * centerGlow;

    // Subtle vignette
    float vignette = 1.0 - centerDist * 0.4;
    finalColor *= vignette;

    // Filmic tone mapping
    finalColor = finalColor / (1.0 + finalColor * 0.5);

    // Output color
    vec3 color = pow(max(finalColor, vec3(0.0)), vec3(0.92));

fragColor = vec4(color, 1.0);
}

aerialsunsetflyover.glsl:
#version 300 es
precision highp float;

uniform float time;
uniform vec2 resolution;
uniform vec2 fullResolution;

out vec4 fragColor;

#define TAU 6.283185307179586
#define PI 3.141592653589793

uniform float speed;          // 0.1-5.0, forward flight speed through terrain
uniform float terrainScale;   // 0.5-10.0, scale of terrain features
uniform float colorSaturation;// 0.0-2.0, vibrancy of terrain color bands
uniform float horizonHaze;    // 0.0-3.0, atmospheric fog density at horizon
uniform float lensIntensity;  // 0.0-2.0, strength of sun corona and lens flare
uniform float complexity;     // 2.0-7.0, FBM octave count for terrain detail

float hash11(float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

float hash21(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx + p3.yz) * p3.zy);
}

float valueNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(i + vec2(0.0, 0.0));
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float gradNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    vec2 ga = hash22(i + vec2(0.0, 0.0)) * 2.0 - 1.0;
    vec2 gb = hash22(i + vec2(1.0, 0.0)) * 2.0 - 1.0;
    vec2 gc = hash22(i + vec2(0.0, 1.0)) * 2.0 - 1.0;
    vec2 gd = hash22(i + vec2(1.0, 1.0)) * 2.0 - 1.0;
    float va = dot(ga, f - vec2(0.0, 0.0));
    float vb = dot(gb, f - vec2(1.0, 0.0));
    float vc = dot(gc, f - vec2(0.0, 1.0));
    float vd = dot(gd, f - vec2(1.0, 1.0));
    return 0.5 + 0.5 * mix(mix(va, vb, u.x), mix(vc, vd, u.x), u.y);
}

// FBM terrain with ridge detail
float fbmTerrain(vec2 p, float octaves) {
    float val = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    float total = 0.0;
    int iOctaves = int(clamp(octaves, 2.0, 7.0));
    for (int i = 0; i < 7; i++) {
        if (i >= iOctaves) break;
        float n = gradNoise(p * freq);
        // Ridge: invert abs
        float ridge = 1.0 - abs(n * 2.0 - 1.0);
        ridge = ridge * ridge;
        val += ridge * amp;
        total += amp;
        freq *= 2.1;
        amp *= 0.48;
    }
    return val / total;
}

// Standard FBM for smooth features
float fbmSmooth(vec2 p, float octaves) {
    float val = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    float total = 0.0;
    int iOctaves = int(clamp(octaves, 2.0, 7.0));
    for (int i = 0; i < 7; i++) {
        if (i >= iOctaves) break;
        val += gradNoise(p * freq) * amp;
        total += amp;
        freq *= 2.0;
        amp *= 0.5;
    }
    return val / total;
}

// Cosine color palette (Inigo Quilez style)
// a, b, c, d are palette coefficients; t is 0-1 gradient position
vec3 cosPalette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(TAU * (c * t + d));
}

// Terrain color palette: electric purples, teals, volcanic oranges, lime greens
vec3 terrainPalette(float t, float saturation) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 0.8, 0.6);
    vec3 d = vec3(0.0, 0.15, 0.4);
    vec3 col = cosPalette(t, a, b, c, d);
    // Boost saturation
    float lum = dot(col, vec3(0.299, 0.587, 0.114));
    return mix(vec3(lum), col, saturation);
}

// Sky gradient: deep violet-indigo top -> magenta band -> warm cream-orange horizon
vec3 skyColor(float horizonT) {
    // horizonT = 0 at top, 1 at horizon
    vec3 topColor    = vec3(0.08, 0.04, 0.22);   // deep violet-indigo
    vec3 midColor    = vec3(0.55, 0.10, 0.42);   // magenta band
    vec3 horizonColor = vec3(1.0, 0.85, 0.55);  // warm cream-orange
    vec3 col;
    if (horizonT < 0.6) {
        col = mix(topColor, midColor, horizonT / 0.6);
    } else {
        col = mix(midColor, horizonColor, (horizonT - 0.6) / 0.4);
    }
    return col;
}

// Atmospheric fog blend: terrain color washes to warm cream-orange with distance
vec3 fogColor(float dist, float hazeDensity) {
    float fogFar  = 300.0;
    float fogNear = 80.0;
    float fogT = clamp((dist - fogNear) / (fogFar - fogNear), 0.0, 1.0);
    fogT = pow(fogT, 0.7) * hazeDensity;
    fogT = clamp(fogT, 0.0, 1.0);
    vec3 haze = vec3(1.0, 0.88, 0.62);
    return haze;
    // caller mixes using fogT
}

float fogFactor(float dist, float hazeDensity) {
    float fogFar  = 300.0;
    float fogNear = 80.0;
    float fogT = clamp((dist - fogNear) / (fogFar - fogNear), 0.0, 1.0);
    fogT = pow(fogT, 0.7);
    return clamp(fogT * hazeDensity, 0.0, 1.0);
}

// Soft sun disc + corona
vec3 sunEffect(vec2 uv, vec2 sunPos, float intensity) {
    float d = length(uv - sunPos);
    float disc = smoothstep(0.04, 0.01, d);
    float corona = exp(-d * 8.0) * 0.6;
    float glow   = exp(-d * 2.5) * 0.4;
    vec3 sunCol  = vec3(1.0, 0.95, 0.75);
    vec3 coronaCol = vec3(1.0, 0.75, 0.35);
    return (disc * sunCol + corona * coronaCol + glow * vec3(1.0, 0.70, 0.30)) * intensity;
}

// Horizontal lens streak
vec3 lensStreak(vec2 uv, vec2 sunPos, float pulse, float intensity) {
    float dy = abs(uv.y - sunPos.y);
    float streak = exp(-dy * dy * 180.0) * 0.35 * (0.6 + 0.4 * pulse);
    float xFade = 1.0 - smoothstep(0.3, 0.8, abs(uv.x - sunPos.x));
    return vec3(1.0, 0.75, 0.3) * streak * xFade * intensity;
}

// Film grain
float filmGrain(vec2 uv, float seed) {
    return hash21(uv * 1000.0 + seed) * 2.0 - 1.0;
}

// Chromatic aberration offset (returns offset amount based on screen edge distance)
float chromaticStrength(vec2 uv) {
    vec2 centered = uv * 2.0 - 1.0;
    float r2 = dot(centered, centered);
    return r2 * r2 * 0.008;
}

// Vignette
float vignette(vec2 uv) {
    vec2 c = uv * 2.0 - 1.0;
    float v = 1.0 - dot(c, c) * 0.35;
    return clamp(v, 0.0, 1.0);
}

void main() {
    vec2 uv = gl_FragCoord.xy / resolution;
    vec2 centered = uv - 0.5;
    centered.x *= resolution.x / resolution.y;

    // ═══════════════════════════════════════════════════════════════════════════
    // LOOPING PRIMITIVES - ALL ANIMATION MUST USE THESE
    // time goes 0→1, so t goes 0→TAU, completing exactly one cycle
    // ═══════════════════════════════════════════════════════════════════════════
    float t = time * TAU;           // Converts time 0→1 to radians 0→TAU
    vec2 timeCircle = vec2(cos(t), sin(t));  // For noise sampling - traces a circle
    float pulse = 0.5 + 0.5 * sin(t);        // 0→1→0 smooth oscillation
    float wave = sin(t);                      // -1→1→-1 smooth oscillation

// ═══════════════════════════════════════════════════════════════════════════
    // CAMERA SETUP
    // ═══════════════════════════════════════════════════════════════════════════

    // Camera position: flying at ~40m altitude with Y-bob
    float camY = 40.0 + wave * 2.5;

    // Lazy lateral banking (roll angle)
    float bankAngle = wave * 0.06;
    float cosBank = cos(bankAngle);
    float sinBank = sin(bankAngle);

    // Ray direction from camera through screen pixel
    // centered.x is already aspect-corrected
    vec2 screenPos = centered; // aspect-corrected centered UV

    // Apply bank rotation to screen space
    vec2 bankedPos;
    bankedPos.x = screenPos.x * cosBank - screenPos.y * sinBank;
    bankedPos.y = screenPos.x * sinBank + screenPos.y * cosBank;

    // FOV ~70 degrees
    float fov = 1.3;
    vec3 rayDir = normalize(vec3(bankedPos.x * fov, bankedPos.y * fov, 1.0));

    // ═══════════════════════════════════════════════════════════════════════════
    // TERRAIN RAYMARCHING
    // ═══════════════════════════════════════════════════════════════════════════

    // Terrain motion: offset XZ using timeCircle for seamless looping
    // timeCircle traces a circle, giving forward+slight-lateral motion
    vec2 terrainOffset = timeCircle * speed * 25.0;

    // Sky vs terrain determination
    // Ground plane intersection: ray from camY downward
    // If rayDir.y >= 0, we're looking at sky

    bool hitTerrain = false;
    float hitDist = 0.0;
    float hitHeight = 0.0;
    vec2 hitXZ = vec2(0.0);

    if (rayDir.y < -0.01) {
        // March along the ray to find where it hits terrain
        // Terrain height is fbmTerrain mapped to ~0-20 units
        float tStep = 0.0;
        float stepSize = 1.0;

        for (int i = 0; i < 80; i++) {
            vec3 pos = vec3(0.0, camY, 0.0) + rayDir * tStep;

            // World XZ position
            vec2 xz = vec2(pos.x, pos.z);

            // Terrain height at this XZ
            vec2 noiseCoord = (xz + terrainOffset) * (terrainScale * 0.08);
            float terrH = fbmTerrain(noiseCoord, complexity) * 18.0;

            float gap = pos.y - terrH;

            if (gap < 0.3) {
                hitTerrain = true;
                hitDist = tStep;
                hitHeight = terrH;
                hitXZ = xz;
                break;
            }

            // Adaptive step: step by gap / 2, min 0.5, max 8
            stepSize = clamp(gap * 0.5, 0.5, 8.0);
            tStep += stepSize;

            if (tStep > 600.0) break;
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // TERRAIN COLOR
    // ═══════════════════════════════════════════════════════════════════════════

    vec3 terrainCol = vec3(0.0);

    if (hitTerrain) {
        // Sample terrain noise at hit point for color variation
        vec2 colorCoord = (hitXZ + terrainOffset) * (terrainScale * 0.08);

        // Multiple noise layers for color bands
        float bandNoise1 = fbmSmooth(colorCoord * 0.7, 4.0);
        float bandNoise2 = fbmSmooth(colorCoord * 1.4 + vec2(3.7, 1.9), 3.0);
        float ridgeVal   = fbmTerrain(colorCoord, complexity);

        // Combine for color palette position
        // Hue drift: add sin(t)*0.4 to palette t-parameter
        float hueDrift = wave * 0.4;
        float palT = bandNoise1 * 0.5 + bandNoise2 * 0.3 + ridgeVal * 0.2 + hueDrift;
        palT = fract(palT); // wrap palette

        terrainCol = terrainPalette(palT, colorSaturation);

        // Ridgeline brightening
        terrainCol += vec3(0.15, 0.12, 0.08) * ridgeVal * ridgeVal;

        // Distance fog
        float fog = fogFactor(hitDist, horizonHaze);
        vec3 haze = vec3(1.0, 0.88, 0.62);
        terrainCol = mix(terrainCol, haze, fog);

        // Perspective depth darkening for near terrain
        float nearDark = 1.0 - smoothstep(0.0, 30.0, hitDist) * 0.0;
        terrainCol *= nearDark;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // SKY
    // ═══════════════════════════════════════════════════════════════════════════

    // Horizon position on screen (accounting for bank)
    // In ray space: horizon is where rayDir.y == 0
    // Screen Y at horizon: bankedPos.y = 0 → screenPos.y = 0 when no bank

    // Compute sky gradient based on ray direction elevation
    float rayElev = rayDir.y; // -1 to +1, 0 = horizon

    // Map ray elevation to sky gradient: 0 at horizon, 1 at top
    float skyT = clamp(rayElev * 2.5 + 0.0, 0.0, 1.0);
    // horizonT = 1 - skyT (1 at horizon, 0 at top)
    float horizonT = 1.0 - skyT;

    vec3 skyCol = skyColor(horizonT);

    // Extra horizon glow brightening
    float horizonGlow = exp(-abs(rayElev) * 6.0) * horizonHaze * 0.5;
    skyCol += vec3(1.0, 0.85, 0.55) * horizonGlow;

    // ═══════════════════════════════════════════════════════════════════════════
    // SUN DISC + CORONA + LENS FLARE
    // ═══════════════════════════════════════════════════════════════════════════

    // Sun position: just above center-horizon in screen space
    // Sun Y oscillates with sin(t)*0.04
    vec2 sunUV = vec2(0.0, 0.03 + wave * 0.04);
    // Convert sunUV to our centered (aspect-corrected) space
    // sunUV is in normalized centered space
    vec2 sunCentered = sunUV * vec2(resolution.x / resolution.y, 1.0);

    // Distance from ray to sun direction (use bankedPos)
    // For sun we use the screen bankedPos directly
    vec2 sunScreenPos = sunUV; // in non-aspect-corrected centered space

    // Lens pulse: sin(t*2.0) for 2 cycles
    float lensPulse = 0.5 + 0.5 * sin(t * 2.0);

    // Sun effect in centered (aspect-corrected) screen space
    vec2 centeredRaw = uv - 0.5; // not aspect-corrected for sun
    vec3 sunContrib = sunEffect(centeredRaw, sunScreenPos, lensIntensity * 1.4);

    // Lens streak
    vec3 streakContrib = lensStreak(centeredRaw, sunScreenPos, lensPulse, lensIntensity * 1.2);

    // ═══════════════════════════════════════════════════════════════════════════
    // COMPOSE SCENE
    // ═══════════════════════════════════════════════════════════════════════════

    vec3 finalColor;

    if (hitTerrain) {
        finalColor = terrainCol;
    } else {
        finalColor = skyCol;
        // Add sun and lens effects to sky
        finalColor += sunContrib;
        finalColor += streakContrib;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // POST-PROCESSING
    // ═══════════════════════════════════════════════════════════════════════════

    // Chromatic aberration at screen edges
    float chromaStr = chromaticStrength(uv);
    vec2 chromaOffset = (uv - 0.5) * chromaStr;

    // Sample color channels with slight offset
    // Red channel shifted outward, blue shifted inward
    vec2 uvR = uv + chromaOffset * 2.0;
    vec2 uvB = uv - chromaOffset * 2.0;

    // Recompute simple chroma for edge pixels using sky/terrain blend
    // For efficiency, modulate R and B channels of finalColor
    // by estimated shift (approximation)
    float chromaEdge = chromaStr * 8.0;
    finalColor.r = mix(finalColor.r, finalColor.r * 1.08, chromaEdge);
    finalColor.b = mix(finalColor.b, finalColor.b * 0.92, chromaEdge);

    // Vignette
    float vig = vignette(uv);
    finalColor *= vig;

    // Film grain
    float grain = filmGrain(uv, pulse);
    finalColor += grain * 0.025;

    // Soft tone mapping / exposure
    finalColor = finalColor / (finalColor + 0.8) * 1.5;
    finalColor = clamp(finalColor, 0.0, 1.0);

    // Slight gamma correction
    finalColor = pow(finalColor, vec3(0.9));

fragColor = vec4(finalColor, 1.0);
}

chromeicosahedroninterior.glsl:
#version 300 es
precision highp float;

uniform float time;
uniform vec2 resolution;

out vec4 fragColor;

#define TAU 6.283185307179586
#define PI 3.141592653589793

uniform int reflections;      // 2-10, number of internal mirror bounces
uniform float glowIntensity;  // 0.0-3.0, brightness of edge glow effect
uniform float chromeShift;    // 0.0-0.1, chromatic aberration strength
uniform float cameraOffset;   // 0.0-0.4, camera distance from center

// Hash functions for procedural generation
float hash(float p) {
    return fract(sin(p * 127.1) * 43758.5453);
}

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec3 hash3(vec2 p) {
    vec3 q = vec3(dot(p, vec2(127.1, 311.7)),
                  dot(p, vec2(269.5, 183.3)),
                  dot(p, vec2(419.2, 371.9)));
    return fract(sin(q) * 43758.5453);
}

// Value noise - pure math, noiseOffset enables animation when passed from main
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Golden ratio for icosahedron geometry
const float PHI = 1.618033988749895;

// Icosahedron SDF - signed distance (negative inside)
float sdIcosahedron(vec3 p, float r) {
    vec3 n = normalize(vec3(PHI, 1.0, 0.0));
    vec3 ap = abs(p);
    float a = dot(ap, n);
    float b = dot(ap, n.yzx);
    float c = dot(ap, n.zxy);
    return max(max(a, b), c) - r;
}

// Get icosahedron face normal at point
vec3 icosahedronNormal(vec3 p) {
    vec3 n = normalize(vec3(PHI, 1.0, 0.0));
    vec3 ap = abs(p);
    vec3 sp = sign(p + 1e-6);

    float a = dot(ap, n);
    float b = dot(ap, n.yzx);
    float c = dot(ap, n.zxy);

    if (a >= b && a >= c) return sp * n;
    if (b >= a && b >= c) return sp.yzx * n.yzx;
    return sp.zxy * n.zxy;
}

// Fresnel reflectance (Schlick approximation)
float fresnel(vec3 viewDir, vec3 normal, float f0) {
    float cosTheta = max(dot(-viewDir, normal), 0.0);
    return f0 + (1.0 - f0) * pow(1.0 - cosTheta, 5.0);
}

// Chrome metallic palette - t is 0-1 position, NOT time
vec3 chromePalette(float t) {
    vec3 silver = vec3(0.9, 0.92, 0.95);
    vec3 cyan = vec3(0.7, 0.9, 1.0);
    vec3 gold = vec3(1.0, 0.95, 0.85);
    vec3 blue = vec3(0.7, 0.75, 0.85);

    t = clamp(t, 0.0, 0.9999);
    float segment = t * 4.0;
    int idx = int(segment);
    float blend = segment - float(idx);

    if (idx == 0) return mix(silver, cyan, blend);
    if (idx == 1) return mix(cyan, blue, blend);
    if (idx == 2) return mix(blue, gold, blend);
    return mix(gold, silver, blend);
}

// Procedural environment for reflections
// noiseOffset passed from main for animation
vec3 proceduralEnvironment(vec3 dir, vec2 noiseOffset) {
    float theta = atan(dir.z, dir.x);
    float phi = asin(clamp(dir.y, -1.0, 1.0));

    float band = sin(theta * 3.0) * cos(phi * 2.0);
    band += noise(vec2(theta, phi) * 5.0 + noiseOffset) * 0.3;

    float palettePos = band * 0.5 + 0.5;
    vec3 col = chromePalette(palettePos);
    col *= 0.8 + 0.2 * noise(dir.xz * 8.0 + noiseOffset);

    return col;
}

// Rotation helpers
vec3 rotateY(vec3 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}

vec3 rotateX(vec3 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(p.x, c * p.y - s * p.z, s * p.y + c * p.z);
}

// Edge glow at grazing angles
float edgeGlow(vec3 viewDir, vec3 normal) {
    float edge = 1.0 - abs(dot(viewDir, normal));
    return pow(max(edge, 0.0), 3.0);
}

// Reflect ray inside icosahedron and accumulate color
vec3 reflectRay(vec3 dir, vec3 normal) {
    return reflect(dir, normal);
}

void main() {
    vec2 uv = gl_FragCoord.xy / resolution;
    vec2 centered = uv - 0.5;
    centered.x *= resolution.x / resolution.y;

    // ═══════════════════════════════════════════════════════════════════════════
    // LOOPING PRIMITIVES - ALL ANIMATION MUST USE THESE
    // time goes 0→1, so t goes 0→TAU, completing exactly one cycle
    // ═══════════════════════════════════════════════════════════════════════════
    float t = time * TAU;           // Converts time 0→1 to radians 0→TAU
    vec2 timeCircle = vec2(cos(t), sin(t));  // For noise sampling - traces a circle
    float pulse = 0.5 + 0.5 * sin(t);        // 0→1→0 smooth oscillation
    float wave = sin(t);                      // -1→1→-1 smooth oscillation

// ═══════════════════════════════════════════════════════════════════════════
    // MAIN EFFECT LOGIC - Chrome Icosahedron Interior
    // ═══════════════════════════════════════════════════════════════════════════

    float icoRadius = 1.0;

    // Camera orbiting inside the icosahedron - uses wave for smooth back-and-forth
    vec3 camPos = vec3(
        timeCircle.x * cameraOffset,
        wave * cameraOffset * 0.3,
        timeCircle.y * cameraOffset
    );

    // Camera look direction with gentle oscillation
    vec3 camTarget = vec3(wave * 0.1, sin(t * 2.0) * 0.05, 0.0);
    vec3 camForward = normalize(camTarget - camPos);
    vec3 camRight = normalize(cross(vec3(0.0, 1.0, 0.0), camForward));
    vec3 camUp = cross(camForward, camRight);

    // Ray direction through pixel
    vec3 rayDir = normalize(camForward + centered.x * camRight + centered.y * camUp);

    // Final accumulated color with chromatic aberration
    vec3 finalColor = vec3(0.0);

    // Trace 3 rays for chromatic aberration (R, G, B channels)
    for (int channel = 0; channel < 3; channel++) {
        float aberrationOffset = (float(channel) - 1.0) * chromeShift;
        vec3 traceDir = normalize(rayDir + camRight * aberrationOffset);
        vec3 traceOrigin = camPos;

        vec3 channelColor = vec3(0.0);
        float channelAtten = 1.0;

        // Reflection bounces inside icosahedron
        for (int bounce = 0; bounce < 10; bounce++) {
            if (bounce >= reflections) break;

            // Ray march to find icosahedron surface from inside
            float marchDist = 0.0;
            vec3 hitPos = traceOrigin;

            for (int step = 0; step < 48; step++) {
                hitPos = traceOrigin + traceDir * marchDist;
                float d = -sdIcosahedron(hitPos, icoRadius);
                if (d < 0.001) break;
                marchDist += max(d * 0.6, 0.002);
                if (marchDist > 4.0) break;
            }

            // Surface normal pointing inward
            vec3 normal = -icosahedronNormal(hitPos);

            // Fresnel - chrome is highly reflective
            float fresnelVal = fresnel(traceDir, normal, 0.85);

            // Edge glow - bright at grazing angles, pulsing
            float glow = edgeGlow(traceDir, normal);
            float pulsingGlow = glow * glowIntensity * (0.7 + 0.5 * pulse);

            // Sample procedural environment in reflection direction
            vec3 reflectDir = reflect(traceDir, normal);
            vec3 envColor = proceduralEnvironment(reflectDir, timeCircle * 0.5);

            // Accumulate environment color through attenuation
            channelColor += channelAtten * envColor * (1.0 - fresnelVal) * 0.4;

            // Add edge glow with animated palette position
            float palettePos = 0.5 + 0.3 * sin(t + float(bounce) * 0.8);
            vec3 glowCol = chromePalette(palettePos);
            channelColor += channelAtten * glowCol * pulsingGlow;

            // Attenuate for next bounce
            channelAtten *= fresnelVal * 0.88;

            // Set up next bounce
            traceDir = reflectDir;
            traceOrigin = hitPos + traceDir * 0.01;
        }

        // Final environment contribution after all bounces
        vec3 finalEnv = proceduralEnvironment(traceDir, timeCircle * 0.5);
        channelColor += channelAtten * finalEnv;

        // Assign to appropriate color channel
        if (channel == 0) finalColor.r = channelColor.r;
        else if (channel == 1) finalColor.g = channelColor.g;
        else finalColor.b = channelColor.b;
    }

    // Add central bright spot with animated intensity
    float centerDist = length(centered);
    float centerGlow = exp(-centerDist * 4.0) * 0.3 * (0.8 + 0.4 * pulse);
    finalColor += chromePalette(pulse) * centerGlow;

    // Subtle vignette
    float vignette = 1.0 - centerDist * 0.4;
    finalColor *= vignette;

    // Filmic tone mapping
    finalColor = finalColor / (1.0 + finalColor * 0.5);

    // Output color
    vec3 color = pow(max(finalColor, vec3(0.0)), vec3(0.92));

fragColor = vec4(color, 1.0);
}
